/**
 * Skeleton screen loaders
 */
@keyframes shine-lines {
    0% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0 50%;
    }
}
.skeleton * {
    background-image: linear-gradient(90deg, #F6F6F6 25%, #EFEFEF 37%, #F6F6F6 63%) !important;
    animation: shine-lines 1.6s ease infinite !important;
    background-size: 400% 100% !important;
}

