/* Splash effect when clicking buttons
*/
.splash {
    display: block;
    position: absolute;
    background-color: var(--content-ui-foreground);
    border-radius: 100%;
    opacity: 0.5;
    transform: scale(0);
}

/* On.click animation effect on buttons
*/
.splash.animate {
    animation: ripple 0.3s linear;
}

@keyframes ripple {
    /* Scale 200% to safely cover the entire button and fade it out
     */
    100% {
        opacity: 0;
        transform: scale(2);
    }
}
/* Arbitrary <button> element
 */
button {
    /* Remove mysterious highlight effect when you click
     */
    outline: 0;
}

/* Special button in audio/video player
 */
.mejs-controls button {
    min-height: initial;
}

